<!doctype html><html lang="id"><head><meta name="viewport" content="width=device-width, initial-scale=1">@if($turnstileConfigured)<script src="https://challenges.cloudflare.com/turnstile/v0/api.js" async defer></script>@endif<style>body{margin:0;background:#fff;font-family:Arial,sans-serif}.box{padding:18px}p{font-size:14px;color:#172A24}.error{color:#b42318;line-height:1.45}</style></head><body><div class="box"><p>Verifikasi keamanan</p>@if($turnstileConfigured)<div class="cf-turnstile" data-sitekey="{{ config('services.turnstile.site_key') }}" data-size="flexible" data-callback="done" data-error-callback="failed"></div>@else<p class="error">CAPTCHA belum dikonfigurasi pada server. Hubungi administrator sistem.</p>@endif</div><script>function done(token){if(window.Turnstile){Turnstile.postMessage(token)}else if(window.webkit&&window.webkit.messageHandlers.Turnstile){window.webkit.messageHandlers.Turnstile.postMessage(token)}}function failed(){document.body.querySelector('.box').insertAdjacentHTML('beforeend','<p class="error">CAPTCHA gagal dimuat. Periksa koneksi internet lalu coba lagi.</p>')}</script></body></html>
